#
# Tab completion for bx-audio. Generated by tools/generate-docs.bxs, do not edit. Print it again with `bx-audio completions bash`.
# Load it with: source <(bx-audio completions bash)
#
_bx_audio_complete() {
    local current_word="${COMP_WORDS[COMP_CWORD]}"
    local command="${COMP_WORDS[1]}"
    local commands="info convert normalize trim loudness master stretch pitch bpm silence waveform speak voices licenses install remove where clean play loopify sprite ffmpeg probe mux pieces render explorer doctor completions version help"
    if [ "$COMP_CWORD" -eq 1 ]; then
        COMPREPLY=($(compgen -W "$commands" -- "$current_word"))
        return
    fi
    case "$command" in
        info)
            COMPREPLY=($(compgen -f -W "" -- "$current_word")) ;;
        convert)
            COMPREPLY=($(compgen -f -W "--bitrate= --bitDepth= --sampleRate= --channels=" -- "$current_word")) ;;
        normalize)
            COMPREPLY=($(compgen -f -W "--targetDb=" -- "$current_word")) ;;
        trim)
            COMPREPLY=($(compgen -f -W "--start= --end=" -- "$current_word")) ;;
        loudness)
            COMPREPLY=($(compgen -f -W "" -- "$current_word")) ;;
        master)
            COMPREPLY=($(compgen -f -W "--target= --truePeakDb= --glue --target=streaming --target=podcast --target=broadcast" -- "$current_word")) ;;
        stretch)
            COMPREPLY=($(compgen -f -W "--rate= --seconds=" -- "$current_word")) ;;
        pitch)
            COMPREPLY=($(compgen -f -W "--semitones=" -- "$current_word")) ;;
        bpm)
            COMPREPLY=($(compgen -f -W "--beats" -- "$current_word")) ;;
        silence)
            COMPREPLY=($(compgen -f -W "--thresholdDb= --min= --trim=" -- "$current_word")) ;;
        waveform)
            COMPREPLY=($(compgen -f -W "--width= --unicode" -- "$current_word")) ;;
        speak)
            COMPREPLY=($(compgen -W "--voice= --out= --file= --speed= --captions= --no-install --offset= --max-chars= --by-clause --sentence-pause= --clause-pause= --paragraph-pause=" -- "$current_word")) ;;
        voices)
            COMPREPLY=($(compgen -W "--lang= --installed --downloadable --excluded --all --license=" -- "$current_word")) ;;
        licenses)
            COMPREPLY=($(compgen -W "" -- "$current_word")) ;;
        install)
            COMPREPLY=($(compgen -W "bryce joe john kathleen kristin en_US-ljspeech-high en_US-ljspeech-medium mike norman reza_ibrahim sam engine" -- "$current_word")) ;;
        remove)
            COMPREPLY=($(compgen -W "bryce joe john kathleen kristin en_US-ljspeech-high en_US-ljspeech-medium mike norman reza_ibrahim sam engine" -- "$current_word")) ;;
        where)
            COMPREPLY=($(compgen -W "" -- "$current_word")) ;;
        clean)
            COMPREPLY=($(compgen -W "engine voices ffmpeg cache all --yes" -- "$current_word")) ;;
        play)
            COMPREPLY=($(compgen -f -W "--volume= --output= --output=speakers --output=null" -- "$current_word")) ;;
        loopify)
            COMPREPLY=($(compgen -f -W "--crossfade=" -- "$current_word")) ;;
        sprite)
            COMPREPLY=($(compgen -f -W "--gap=" -- "$current_word")) ;;
        ffmpeg)
            COMPREPLY=($(compgen -W "status install" -- "$current_word")) ;;
        probe)
            COMPREPLY=($(compgen -f -W "" -- "$current_word")) ;;
        mux)
            COMPREPLY=($(compgen -f -W "--keep-original --offset=" -- "$current_word")) ;;
        pieces)
            COMPREPLY=($(compgen -W "" -- "$current_word")) ;;
        render)
            COMPREPLY=($(compgen -W "pop-drive lofi house ambient techno synthwave cinematic chiptune sfx jazz rock voiceover trailer game-audio theme sampler --out= --bars= --bpm= --style= --swing= --seed= --track= --loops= --sound= --choruses= --voice= --speed= --text= --duck= --seconds= --target=" -- "$current_word")) ;;
        explorer)
            COMPREPLY=($(compgen -W "--port=" -- "$current_word")) ;;
        doctor)
            COMPREPLY=($(compgen -W "" -- "$current_word")) ;;
        completions)
            COMPREPLY=($(compgen -W "bash zsh fish powershell" -- "$current_word")) ;;
        version)
            COMPREPLY=($(compgen -W "" -- "$current_word")) ;;
        help)
            COMPREPLY=($(compgen -W "info convert normalize trim loudness master stretch pitch bpm silence waveform speak voices licenses install remove where clean play loopify sprite ffmpeg probe mux pieces render explorer doctor completions version help" -- "$current_word")) ;;
        *) COMPREPLY=($(compgen -f -- "$current_word")) ;;
    esac
}
complete -o filenames -F _bx_audio_complete bx-audio
